     and position('trial-email-0212' in pg_get_functiondef('public.event_site_send(uuid,text,text,boolean,text)'::regprocedure)) > 0
     and to_regprocedure('public.booklet_send__pre0212(uuid,text,text,boolean,text)') is not null
     and to_regprocedure('public.event_site_send__pre0212(uuid,text,text,boolean,text)') is not null
     and has_function_privilege('authenticated', 'public.booklet_send(uuid,text,text,boolean,text)', 'execute')
     and not has_function_privilege('authenticated', 'public.booklet_send__pre0212(uuid,text,text,boolean,text)', 'execute')),
  ('05 edge-function gates: service role only; my_trial_messaging for signed-in members',
     has_function_privilege('service_role', 'public.trial_email_gate(uuid,uuid,uuid,text,text)', 'execute')
     and not has_function_privilege('authenticated', 'public.trial_email_gate(uuid,uuid,uuid,text,text)', 'execute')
     and has_function_privilege('service_role', 'public.trial_email_otp_begin(uuid,text)', 'execute')
     and not has_function_privilege('anon', 'public.trial_email_otp_begin(uuid,text)', 'execute')
     and has_function_privilege('authenticated', 'public.my_trial_messaging()', 'execute')
     and not has_function_privilege('anon', 'public.my_trial_messaging()', 'execute')),
  ('06 WhatsApp / SMS / payment-link guards unchanged (0179 / 0187 wrappers still in place)',
     position('tb-msg-0179' in pg_get_functiondef('public.wa_otp_begin(uuid,text,text)'::regprocedure)) > 0
     and position('tb-msg-0179' in pg_get_functiondef('public.otp_send_authorize(uuid,text)'::regprocedure)) > 0
     and position('tb-msg-0179' in pg_get_functiondef('public.whatsapp_authorize(uuid,text)'::regprocedure)) > 0
     and position('trial-outbound-0187' in pg_get_functiondef('public.payment_link_begin(uuid,integer)'::regprocedure)) > 0),
  ('07 trial terms version = public/trial-facts.js; the e-mail ledger is kept by the trial retention',
     public._trial_terms_version() = 'trial-2026-10-19'
     and (to_regprocedure('public._tr184_keep_tables()') is null or 'trial_email_sends' = any(public._tr184_keep_tables()))),
  ('08 the e-mail ledger has the studio read-only guard',
     exists (select 1 from pg_trigger where tgrelid = 'public.trial_email_sends'::regclass and tgname = 'zzz_studio_read_only')),
  ('09 no paid studio is treated as an e-mail trial',
     not exists (select 1 from public.studio_subscriptions s where s.status = 'active' and public._tr212_email_ok(s.org_id)))
) v(item, ok)
union all
select '0213 ' || item as item, ok from (values
  ('01 helpers internal (no app / anonymous access)',
     not has_function_privilege('authenticated', 'public._a213_sample_layout(text)', 'execute')
     and not has_function_privilege('authenticated', 'public._a213_fill_floor(uuid)', 'execute')
     and not has_function_privilege('authenticated', 'public._a213_fill_trial_layouts(uuid)', 'execute')
     and not has_function_privilege('anon', 'public._a213_fill_trial_layouts(uuid)', 'execute')
     and not has_function_privilege('anon', 'public._a213_manifest_note()', 'execute')),
  ('02 sample master: SMP-1000 / 1002 / 1004 / 1005 / 1006 open on a floor plan that seats exactly their guests, within the limit',
     not exists (select 1 from public.organizations o where o.id = 'a5a5a5a5-0166-4000-8000-000000000001' and o.is_sample_master)
     or (select count(*) from public.quotes q
           join public.quote_versions v on v.quote_id = q.id and v.version_no = greatest(coalesce(q.current_version, 1), 1)
          where q.org_id = 'a5a5a5a5-0166-4000-8000-000000000001' and q.deleted_at is null
            and q.code in ('SMP-1000', 'SMP-1002', 'SMP-1004', 'SMP-1005', 'SMP-1006')
            and v.object_count > 0 and (q.client ->> 'guests') ~ '^[0-9]+$'
            and (select coalesce(sum(case when (i -> 'properties' ->> 'rows') ~ '^[0-9]+$' and (i -> 'properties' ->> 'cols') ~ '^[0-9]+$'
                                then (i -> 'properties' ->> 'rows')::int * (i -> 'properties' ->> 'cols')::int
                              when (i -> 'properties' ->> 'seats') ~ '^[0-9]+$' then (i -> 'properties' ->> 'seats')::int
                              else 0 end), 0)
         from jsonb_array_elements(coalesce(v.data -> 'items', '[]'::jsonb)) i) = (q.client ->> 'guests')::int
            and (q.client ->> 'guests')::int <= (v.data #>> '{venue,capacity}')::int) = 5),
  ('03 sample master: the wedding (SMP-1001) and gala (SMP-1003) plans still there',
     not exists (select 1 from public.organizations o where o.id = 'a5a5a5a5-0166-4000-8000-000000000001' and o.is_sample_master)
     or (select count(*) from public.quotes q join public.quote_versions v on v.quote_id = q.id
          where q.org_id = 'a5a5a5a5-0166-4000-8000-000000000001' and q.code in ('SMP-1001', 'SMP-1003') and v.object_count > 0) >= 2),
  ('04 the 0213 sample version was published once and is current (or a later one) with the floor plans in it',
     not exists (select 1 from public.organizations o where o.id = 'a5a5a5a5-0166-4000-8000-000000000001' and o.is_sample_master)
     or ((select count(*) from public.helm_trial_seed_manifest where notes = public._a213_manifest_note()) = 1
         and exists (select 1 from public.helm_trial_seed_manifest c where c.is_current
                       and c.version >= (select m.version from public.helm_trial_seed_manifest m where m.notes = public._a213_manifest_note())
                       and (select count(*) from jsonb_array_elements(coalesce(c.payload #> '{tables,quote_versions}', '[]'::jsonb)) x
                             where (x ->> 'object_count')::int > 0) >= 7)))
) v(item, ok)
union all
select '0220 ' || item as item, ok from (values
  ('01 start_blank_quote is the 0220 body (strict untouched test), security definer, search_path empty',
     (select p.prosecdef and 'search_path=""' = any(p.proconfig) and p.prosrc like '%start-blank-0220%'
             and p.prosrc like '%_blank_quote_touched_reason%' and p.prosrc like '%pg_advisory_xact_lock%'
        from pg_proc p where p.oid = 'public.start_blank_quote(text,text)'::regprocedure)),
  ('02 start_blank_quote: signed-in members can call it, signed-out cannot; only ONE start_blank_quote',
     has_function_privilege('authenticated', 'public.start_blank_quote(text,text)', 'execute')
     and not has_function_privilege('anon', 'public.start_blank_quote(text,text)', 'execute')
     and (select count(*) from pg_proc where proname = 'start_blank_quote' and pronamespace = 'public'::regnamespace) = 1),
  ('03 internal helpers are not callable from the app',
     not has_function_privilege('authenticated', 'public._blank_quote_touched_reason(uuid,uuid)', 'execute')
     and not has_function_privilege('anon', 'public._blank_quote_touched_reason(uuid,uuid)', 'execute')
     and not has_function_privilege('authenticated', 'public._bk220_layout_auto_on(uuid,integer)', 'execute')
     and not has_function_privilege('anon', 'public._bk220_layout_auto_on(uuid,integer)', 'execute')),
  ('04 client_booklets.sections_set_at exists (nullable)',
     exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'client_booklets'
              and column_name = 'sections_set_at' and is_nullable = 'YES')),
  ('05 trigger zzzz_bk220_layout_auto_on is on quote_versions (after insert)',
     exists (select 1 from pg_trigger where tgname = 'zzzz_bk220_layout_auto_on' and tgrelid = 'public.quote_versions'::regclass and not tgisinternal)),
  ('06 booklet_layout_auto_on + booklet_set_sections: signed-in only',
     has_function_privilege('authenticated', 'public.booklet_layout_auto_on(uuid)', 'execute')
     and has_function_privilege('authenticated', 'public.booklet_set_sections(uuid,jsonb)', 'execute')
     and not has_function_privilege('anon', 'public.booklet_layout_auto_on(uuid)', 'execute')
     and not has_function_privilege('anon', 'public.booklet_set_sections(uuid,jsonb)', 'execute')),
  ('07 booklet_current returns sections + image_variants, still signed-in only',
     (select prosrc like '%booklet-layout-0220%' and prosrc like '%image_variants%' from pg_proc where oid = 'public.booklet_current(uuid)'::regprocedure)
     and not has_function_privilege('anon', 'public.booklet_current(uuid)', 'execute')),
  ('08 the public booklet reader is unchanged (still the 0083 body, anon may read)',
     (select prosrc like '%booklet-images-0083%' from pg_proc where oid = 'public.public_get_booklet(uuid)'::regprocedure)
     and has_function_privilege('anon', 'public.public_get_booklet(uuid)', 'execute'))
) v(item, ok)
union all
select '0222 ' || item as item, ok from (values
  ('01 re-pricing alerts skip sample data, confirmed events and client-approved / paid quotes (0082 rules kept)',
     position('trial-seed-0222' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public._r3_price_change_notify(uuid,text,text[],text)')), '')) > 0
     and position('not coalesce(q.is_demo, false)' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public._r3_price_change_notify(uuid,text,text[],text)')), '')) > 0
     and position('q.deleted_at is null and q.archived_at is null' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public._r3_price_change_notify(uuid,text,text[],text)')), '')) > 0),
  ('02 sample master: every open sample quote is priced at its Control Center chair rate',
     not exists (select 1 from public.quotes q
                  join public.app_config c on c.org_id = q.org_id and c.key = 'pricing'
                  where q.org_id = 'a5a5a5a5-0166-4000-8000-000000000001' and q.deleted_at is null
                    and coalesce(q.status, '') <> 'cancelled' and coalesce(q.lifecycle_stage, 'quote') not in ('settlement', 'closed')
                    and coalesce((q.pricing ->> 'chairs'), '0') <> '0'
                    and (q.pricing ->> 'chairPrice') is distinct from (c.value ->> 'chairPrice'))),
  ('03 sample master: confirmed events - milestones add up to the total',
     not exists (select 1 from public.quotes q where q.org_id = 'a5a5a5a5-0166-4000-8000-000000000001' and q.status = 'confirmed'
                  and exists (select 1 from public.payment_milestones pm where pm.quote_id = q.id)
                  and (select sum(pm.amount) from public.payment_milestones pm where pm.quote_id = q.id) <> (q.pricing ->> 'total')::numeric)),
  ('04 the 0222 sample version was published once and is current (or a later one)',
     (select count(*) from public.helm_trial_seed_manifest where notes = public._a222_manifest_note()) = 1
     and exists (select 1 from public.helm_trial_seed_manifest c where c.is_current
                   and c.version >= (select m.version from public.helm_trial_seed_manifest m where m.notes = public._a222_manifest_note()))),
  ('05 helpers internal',
     not has_function_privilege('authenticated', 'public._r3_price_change_notify(uuid,text,text[],text)', 'execute')
     and not has_function_privilege('anon', 'public._r3_price_change_notify(uuid,text,text[],text)', 'execute')
     and not has_function_privilege('authenticated', 'public._a222_manifest_note()', 'execute'))
) v(item, ok)
union all
select '0223 ' || item as item, ok from (values
  ('01 my_trial_status + hq_trial_info re-issued (studio zone)',
     position('trial-dates-0223' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public.my_trial_status()')), '')) > 0
     and position('trial-dates-0223' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public.hq_trial_info(uuid)')), '')) > 0
     and position('_td223_zone' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public.my_trial_status()')), '')) > 0),
  ('02 grants: the RPCs signed-in only, the helper internal',
     has_function_privilege('authenticated', 'public.my_trial_status()', 'execute')
     and not has_function_privilege('anon', 'public.my_trial_status()', 'execute')
     and has_function_privilege('authenticated', 'public.hq_trial_info(uuid)', 'execute')
     and not has_function_privilege('anon', 'public.hq_trial_info(uuid)', 'execute')
     and not has_function_privilege('authenticated', 'public._td223_zone(uuid)', 'execute')
     and not has_function_privilege('anon', 'public._td223_zone(uuid)', 'execute')),
  ('03 zone helper: a bad / missing zone falls back to Asia/Kolkata',
     public._td223_zone(null) = 'Asia/Kolkata'),
  ('04 days counted in the studio zone; ended from the exact end moment',
     position('at time zone v_tz' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public.my_trial_status()')), '')) > 0
     and position('v_end <= now()' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public.my_trial_status()')), '')) > 0
     and position('''timezone'', public._td223_zone(p_org)' in coalesce((select prosrc from pg_proc where oid = to_regprocedure('public.hq_trial_info(uuid)')), '')) > 0)
) v(item, ok)
) z order by item;
